import {
  ChevronRight,
  FolderGit2,
  FolderPlus,
  LayoutDashboard,
  PanelLeft,
  PanelLeftClose,
  Plus,
  Search,
  Settings2,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { cn } from "../lib/cn";
import { isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";
import type { RegisteredProject } from "../lib/tauri";
import type { ActiveAgent, DirtyState, Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { WorktreeList } from "./WorktreeList";

export const SIDEBAR_WIDTH_STORAGE_KEY = "orca.sidebar.width";
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  open?: boolean;
  isMac?: boolean;
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: () => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette: () => void;
  onOpenSettings?: () => void;
  onToggle?: () => void;
  onHide?: () => void;
};

export function Sidebar({
  open = true,
  isMac = isMacShortcutPlatform(),
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenCommandPalette,
  onOpenSettings,
  onToggle,
  onHide,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const focusWorktrees = () => {
    worktreeRegionRef.current?.focus();
    worktreeRegionRef.current?.scrollIntoView?.({ block: "start" });
  };

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  if (!open) {
    const collapsedWidth = isMac ? 108 : 36;
    return (
      <aside
        className="relative flex h-full shrink-0 flex-col overflow-hidden border-r border-worktree-sidebar-border bg-worktree-sidebar text-worktree-sidebar-foreground"
        style={{ width: `${collapsedWidth}px` }}
      >
        <div
          data-testid="sidebar-drag-region"
          data-tauri-drag-region
          className="drag-region flex h-titlebar shrink-0 items-center justify-end px-2"
        >
          {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : null}
          <IconButton
            label="Show sidebar"
            className="no-drag"
            size="sm"
            onClick={onToggle}
          >
            <PanelLeft className="size-3.5" />
          </IconButton>
        </div>
        <div className="flex-1" />
      </aside>
    );
  }

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center justify-between px-2"
      >
        {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : <div />}
        <IconButton
          label="Hide sidebar"
          className="no-drag"
          size="sm"
          onClick={onToggle ?? onHide}
        >
          <PanelLeftClose className="size-3.5" />
        </IconButton>
      </div>

      <div className="space-y-1 px-2 pb-1">
        <button
          type="button"
          onClick={focusWorktrees}
          className="flex h-7 w-full items-center gap-2 rounded-md bg-worktree-sidebar-accent px-2 text-left text-[13px] font-medium tracking-tight text-worktree-sidebar-accent-foreground"
        >
          <LayoutDashboard className="size-3.5" />
          <span className="flex-1">Workspace</span>
        </button>
        <button
          type="button"
          onClick={onOpenCommandPalette}
          className="group relative flex h-7 w-full items-center rounded-md border border-worktree-sidebar-border/70 bg-worktree-sidebar-foreground/5 pl-7 pr-1.5 text-left text-[12px] font-medium tracking-tight text-worktree-sidebar-foreground/45 transition-colors hover:border-worktree-sidebar-border hover:bg-worktree-sidebar-foreground/8"
        >
          <Search className="pointer-events-none absolute left-2 top-1/2 size-3 -translate-y-1/2 text-worktree-sidebar-foreground/30" />
          Search workspaces
          <kbd className="ml-auto rounded border border-worktree-sidebar-border/80 bg-worktree-sidebar-foreground/8 px-1 py-px text-[9px] text-worktree-sidebar-foreground/55">
            {shortcutLabel("commandPalette.open")}
          </kbd>
        </button>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <SectionHeader
          title="Projects"
          count={projects.length}
          actions={
            <>
              <IconButton label="Add worktree" size="sm" onClick={onCreateWorktree}>
                <FolderPlus className="size-3.5" />
              </IconButton>
              <IconButton label="Add project" size="sm" onClick={onAddProject}>
                <Plus className="size-3.5" />
              </IconButton>
            </>
          }
        />

        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-2 pb-2 scrollbar-sleek">
          {projects.length === 0 ? (
            <p className="px-2 py-3 text-[11px] leading-relaxed text-muted-foreground">
              No projects registered yet.
            </p>
          ) : null}

          {projects.map((project) => {
            const expanded = project.workspaceId === activeProjectId;
            return (
              <div key={project.workspaceId} className="pb-0.5">
                <button
                  type="button"
                  onClick={() => onSelectProject(project)}
                  aria-expanded={expanded}
                  className={cn(
                    "flex h-7 w-full items-center gap-1.5 rounded-md px-1.5 text-left text-[12px] transition-colors",
                    "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                    expanded
                      ? "bg-worktree-sidebar-accent font-medium text-worktree-sidebar-accent-foreground"
                      : "text-worktree-sidebar-foreground/65 hover:bg-worktree-sidebar-accent/60 hover:text-worktree-sidebar-foreground",
                  )}
                >
                  <ChevronRight
                    aria-hidden="true"
                    className={cn(
                      "size-3 shrink-0 text-muted-foreground transition-transform",
                      expanded && "rotate-90",
                    )}
                  />
                  <FolderGit2 className="size-3.5 shrink-0" />
                  <span className="min-w-0 flex-1 truncate">{project.workspaceId}</span>
                </button>

                {expanded ? (
                  <div className="pl-3 pr-0.5 pt-0.5">
                    <WorktreeList
                      worktrees={worktrees}
                      agents={agents}
                      activePath={activePath}
                      statuses={statuses}
                      onSelect={onSelectWorktree}
                      onCreate={onCreateWorktree}
                      onRefreshStatus={onRefreshWorktreeStatus}
                      onDelete={onDeleteWorktree}
                      label={`${project.workspaceId} worktrees`}
                    />
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex shrink-0 items-center justify-between border-t border-worktree-sidebar-border px-2 py-1.5">
        <div className="flex items-center gap-2 px-1 text-[10px] text-muted-foreground">
          <span className="size-1.5 rounded-full bg-status-success" />
          Local runtime
        </div>
        <IconButton label="Settings" size="sm" onClick={onOpenSettings}>
          <Settings2 className="size-3.5" />
        </IconButton>
      </div>

      <div
        role="separator"
        aria-label="Resize sidebar"
        aria-orientation="vertical"
        aria-valuemin={MIN_SIDEBAR_WIDTH}
        aria-valuemax={MAX_SIDEBAR_WIDTH}
        aria-valuenow={width}
        onPointerDown={startResize}
        className="no-drag absolute inset-y-0 right-0 z-30 w-1.5 cursor-col-resize touch-none"
      >
        <span className="pointer-events-none absolute inset-y-0 right-0 w-px bg-worktree-sidebar-border transition-colors group-hover:bg-ring/45" />
      </div>
    </aside>
  );
}

function loadSidebarWidth() {
  try {
    const stored = Number(window.localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY));
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type { Worktree } from "../lib/types";
import { SIDEBAR_WIDTH_STORAGE_KEY, Sidebar } from "./Sidebar";

const worktree: Worktree = {
  path: "/repo/main",
  head: "abc123",
  branch: "refs/heads/orca/ws/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

beforeEach(() => localStorage.clear());
afterEach(cleanup);

const projects = [
  { workspaceId: "maho-workspace", repoRoot: "/repos/maho-workspace" },
  { workspaceId: "content-intel-dashboard", repoRoot: "/repos/content-intel-dashboard" },
];

function baseProps(overrides: Record<string, unknown> = {}) {
  return {
    worktrees: [worktree],
    agents: [],
    activePath: worktree.path,
    onSelectWorktree: vi.fn(),
    onCreateWorktree: vi.fn(),
    onAddProject: vi.fn(),
    onOpenCommandPalette: vi.fn(),
    onOpenSettings: vi.fn(),
    ...overrides,
  } as any;
}

function renderSidebar(overrides: Record<string, unknown> = {}) {
  return render(<Sidebar {...baseProps(overrides)} />);
}

describe("Sidebar navigation", () => {
  it("uses the 236px parity width by default", () => {
    renderSidebar();
    expect(screen.getByRole("complementary")).toHaveStyle({ width: "236px" });
  });

  it("keeps Workspace and Search functional and exposes Add Project", () => {
    const onOpenCommandPalette = vi.fn();
    const onAddProject = vi.fn();
    renderSidebar({ onOpenCommandPalette, onAddProject });

    expect(screen.queryByText("Agents")).not.toBeInTheDocument();
    expect(screen.queryByText("Active agents")).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: /search workspaces/i }));
    expect(onOpenCommandPalette).toHaveBeenCalledOnce();

    fireEvent.click(screen.getByRole("button", { name: "Workspace" }));
    expect(screen.getByTestId("worktree-region")).toHaveFocus();

    fireEvent.click(screen.getByRole("button", { name: "Add project" }));
    expect(onAddProject).toHaveBeenCalledOnce();
  });

  it("nests each project's worktrees inside that project's own tree group", () => {
    renderSidebar({ projects, activeProjectId: "maho-workspace" });

    // A single "Projects" section owns the tree — there is no disjoint "Worktrees" section.
    expect(screen.getByText("Projects")).toBeInTheDocument();
    expect(screen.queryByText("Worktrees")).not.toBeInTheDocument();

    const activeProject = screen.getByRole("button", { name: /maho-workspace/ });
    const collapsedProject = screen.getByRole("button", { name: /content-intel-dashboard/ });
    expect(activeProject).toHaveAttribute("aria-expanded", "true");
    expect(collapsedProject).toHaveAttribute("aria-expanded", "false");

    // The worktree list is a descendant of the expanded project's group, not a sibling section.
    const group = screen.getByRole("list", { name: "maho-workspace worktrees" });
    expect(activeProject.parentElement).toContainElement(group);
    expect(group).toContainElement(screen.getByRole("button", { name: /main/ }));

    // The collapsed project renders no worktrees of its own.
    expect(screen.queryByRole("list", { name: "content-intel-dashboard worktrees" })).not.toBeInTheDocument();
  });

  it("selects a project from its tree row and a worktree from inside the nested group", () => {
    const onSelectProject = vi.fn();
    const onSelectWorktree = vi.fn();
    renderSidebar({ projects, activeProjectId: "maho-workspace", onSelectProject, onSelectWorktree });

    fireEvent.click(screen.getByRole("button", { name: /content-intel-dashboard/ }));
    expect(onSelectProject).toHaveBeenCalledWith(projects[1]);

    const group = screen.getByRole("list", { name: "maho-workspace worktrees" });
    fireEvent.click(within(group).getByRole("button", { name: /main/ }));
    expect(onSelectWorktree).toHaveBeenCalledWith(worktree);
  });

  it("marks the active worktree inside the nested group as current", () => {
    renderSidebar({ projects, activeProjectId: "maho-workspace", activePath: worktree.path });

    const group = screen.getByRole("list", { name: "maho-workspace worktrees" });
    expect(within(group).getByRole("button", { name: /main/ })).toHaveAttribute("aria-current", "true");
  });

  it("marks only the noninteractive titlebar background as a Tauri drag region", () => {
    renderSidebar();
    const dragBackground = screen.getByTestId("sidebar-drag-region");
    expect(dragBackground).toHaveAttribute("data-tauri-drag-region");
    expect(screen.getByRole("button", { name: "Hide sidebar" })).toHaveClass("no-drag");
    expect(screen.getByRole("separator", { name: "Resize sidebar" })).toHaveClass("no-drag");
  });

  it("restores, drags, clamps, and persists sidebar width", () => {
    localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, "390");
    renderSidebar();

    const sidebar = screen.getByRole("complementary");
    const handle = screen.getByRole("separator", { name: "Resize sidebar" });
    expect(sidebar).toHaveStyle({ width: "390px" });

    fireEvent.pointerDown(handle, { clientX: 390, pointerId: 1 });
    fireEvent.pointerMove(window, { clientX: 600, pointerId: 1 });
    expect(sidebar).toHaveStyle({ width: "420px" });
    fireEvent.pointerUp(window, { clientX: 600, pointerId: 1 });
    expect(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY)).toBe("420");

    fireEvent.pointerDown(handle, { clientX: 420, pointerId: 2 });
    fireEvent.pointerMove(window, { clientX: 40, pointerId: 2 });
    expect(sidebar).toHaveStyle({ width: "220px" });
    fireEvent.pointerUp(window, { clientX: 40, pointerId: 2 });
    expect(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY)).toBe("220");
  });

  it("renders exactly one visible sidebar divider without redundant aside border", () => {
    renderSidebar();
    const sidebar = screen.getByRole("complementary");
    expect(sidebar).not.toHaveClass("border-r");
    expect(sidebar).not.toHaveClass("border-worktree-sidebar-border");

    const separator = screen.getByRole("separator", { name: "Resize sidebar" });
    expect(separator).toBeInTheDocument();
    expect(separator.querySelector(".bg-worktree-sidebar-border")).toBeInTheDocument();
  });

  it("calls onToggle or onHide when Hide sidebar button is clicked", () => {
    const onToggle = vi.fn();
    renderSidebar({ onToggle });

    fireEvent.click(screen.getByRole("button", { name: "Hide sidebar" }));
    expect(onToggle).toHaveBeenCalledOnce();
  });

  it("renders collapsed sidebar strip when open is false", () => {
    const onToggle = vi.fn();
    renderSidebar({ open: false, isMac: true, onToggle });

    const sidebar = screen.getByRole("complementary");
    expect(sidebar).toHaveStyle({ width: "108px" });
    expect(screen.getByTestId("titlebar-traffic-light-pad")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Hide sidebar" })).not.toBeInTheDocument();

    const showButton = screen.getByRole("button", { name: "Show sidebar" });
    expect(showButton).toBeInTheDocument();
    expect(showButton).toHaveClass("no-drag");

    fireEvent.click(showButton);
    expect(onToggle).toHaveBeenCalledOnce();
  });
});

import { GitBranch, LockKeyhole, RefreshCcw, Trash2 } from "lucide-react";

import { cn } from "../lib/cn";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { StatusDot } from "./ui/StatusDot";

type WorktreeListProps = {
  worktrees: Worktree[];
  activePath: string;
  agents: ActiveAgent[];
  statuses: Record<string, DirtyState | undefined>;
  onSelect: (worktree: Worktree) => void;
  onCreate: () => void;
  onRefreshStatus: (worktree: Worktree) => void;
  onDelete: (worktree: Worktree) => void;
  label?: string;
};

function basename(path: string) {
  if (path === ".") return "main";
  return path.split(/[\\/]/).filter(Boolean).at(-1) ?? path;
}

function branchName(worktree: Worktree) {
  return worktree.branch?.replace(/^refs\/heads\//, "") ?? "detached HEAD";
}

function workspaceName(worktree: Worktree) {
  const parts = branchName(worktree).split("/");
  return parts[0] === "orca" && parts.length > 2 ? parts.slice(2).join("/") : basename(worktree.path);
}

/** The repository root worktree is the one that is not an `orca/<ws>/<slug>` worktree branch. */
function isPrimaryWorktree(worktree: Worktree) {
  return worktreeIdentity(worktree) === null;
}

export function WorktreeList({
  worktrees,
  activePath,
  agents,
  statuses,
  onSelect,
  onCreate,
  onRefreshStatus,
  onDelete,
  label = "Worktrees",
}: WorktreeListProps) {
  if (worktrees.length === 0) {
    return (
      <div className="border-l border-worktree-sidebar-border py-2 pl-3 pr-2 text-[11px] leading-relaxed text-muted-foreground">
        <p>No Git worktrees found for this repository.</p>
        <button
          type="button"
          onClick={onCreate}
          className="mt-1 rounded-sm text-[11px] font-medium text-worktree-sidebar-foreground/70 underline-offset-2 transition-colors hover:text-worktree-sidebar-foreground hover:underline focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        >
          Create the first worktree
        </button>
      </div>
    );
  }

  return (
    <ul aria-label={label} className="m-0 list-none p-0">
      {worktrees.map((worktree) => {
        const active = worktree.path === activePath;
        const agent = agents.find((candidate) => candidate.worktreePath === worktree.path);
        const status = statuses[worktree.path];
        const primary = isPrimaryWorktree(worktree);
        const canDelete = !primary;
        return (
          <li
            key={worktree.path}
            className={cn(
              "group/worktree-row relative border-l transition-colors",
              active
                ? "border-worktree-sidebar-ring/60 bg-worktree-sidebar-accent"
                : "border-worktree-sidebar-border hover:bg-worktree-sidebar-accent/45",
            )}
          >
            <button
              type="button"
              onClick={() => onSelect(worktree)}
              aria-current={active ? "true" : undefined}
              className="w-full rounded-sm py-1.5 pl-2 pr-14 text-left focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            >
              <span className="flex min-w-0 items-start gap-1.5">
                <span className="mt-0.5 flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                  <GitBranch className="size-3" />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1.5">
                    {agent ? <StatusDot state={agent.state} /> : <span className="size-1.5 shrink-0 rounded-full bg-status-idle" />}
                    <span className="min-w-0 flex-1 truncate text-[12px] font-medium leading-tight text-foreground">
                      {workspaceName(worktree)}
                    </span>
                    {primary ? (
                      <span className="shrink-0 rounded-full bg-worktree-sidebar-foreground/10 px-1.5 py-px text-[10px] font-medium leading-none text-muted-foreground">
                        primary
                      </span>
                    ) : null}
                  </span>
                  <span className="mt-0.5 block truncate font-mono text-[9px] leading-snug text-muted-foreground/75">
                    {branchName(worktree)}
                  </span>
                  <span className={cn("mt-0.5 block text-[9px]", status?.isDirty ? "text-status-warning" : "text-muted-foreground/75")}>
                    {status ? (status.isDirty ? `Dirty · ${status.files.length} ${status.files.length === 1 ? "file" : "files"}` : "Clean") : "Status not checked"}
                  </span>
                  {agent ? (
                    <span className="mt-0.5 flex items-center gap-1.5 truncate text-[9px] text-muted-foreground/75">
                      <span className="truncate">{agent.name}</span>
                      <span aria-hidden="true">·</span>
                      <span className="truncate">{agent.task}</span>
                    </span>
                  ) : null}
                </span>
              </span>
            </button>

            <div className="absolute right-1 top-1 flex items-center gap-0.5 opacity-55 transition-opacity focus-within:opacity-100 group-hover/worktree-row:opacity-100">
              {worktree.locked ? <LockKeyhole className="mr-0.5 size-3 text-status-warning" /> : null}
              <IconButton label="Refresh worktree status" size="sm" onClick={() => onRefreshStatus(worktree)}>
                <RefreshCcw className="size-3" />
              </IconButton>
              <IconButton label="Delete worktree" size="sm" disabled={!canDelete} onClick={() => onDelete(worktree)}>
                <Trash2 className="size-3" />
              </IconButton>
            </div>
          </li>
        );
      })}
    </ul>
  );
}

import { invoke, isTauri } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type {
  BranchDeletionPreview,
  DirtyState,
  StructuredIpcError,
  TerminalLifecyclePayload,
  TerminalOutputPayload,
  TerminalSessionSummary,
  TerminalSignal,
  Worktree,
  WorktreeChangedPayload,
  WorktreeIdentity,
} from "./types";

export const DEFAULT_WORKSPACE_ID = "default";

export type RegisteredProject = {
  workspaceId: string;
  repoRoot: string;
};

export type LocalBranch = {
  name: string;
  isCurrent: boolean;
};

export type TerminalPreferences = {
  fontFamily: string;
  macosOptionAsAlt: boolean;
  source: "defaults" | "ghostty";
  status: "imported" | "absent" | "malformed";
  sourcePath: string | null;
};

type WorktreeStatusRequest = {
  workspaceId: string;
  worktree: WorktreeIdentity;
};

type DeleteWorktreeRequest = WorktreeStatusRequest & {
  deleteBranch?: boolean | null;
};

export function isTauriRuntime() {
  return isTauri();
}

export async function registerProject(request: { workspaceId: string; repoPath: string }) {
  return invokeCommand<RegisteredProject>("cmd_project_register", { request });
}

export async function listProjectBranches(workspaceId: string) {
  return invokeCommand<LocalBranch[]>("cmd_project_branches", { request: { workspaceId } });
}

