// Accordion state is stored as the set of *collapsed* projects so that a project the user
// never touched follows the default (expanded when active) instead of being pinned open.
const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(loadCollapsedProjects);
const knownProjectsRef = useRef<Set<string>>(new Set(loadCollapsedProjects()));

useEffect(() => {
  // Projects the sidebar has never seen start collapsed unless they are the active project.
  const unseen = projects.filter((project) => !knownProjectsRef.current.has(project.workspaceId));
  if (unseen.length === 0) return;
  for (const project of unseen) knownProjectsRef.current.add(project.workspaceId);
  const defaultsCollapsed = unseen.filter((project) => project.workspaceId !== activeProjectId);
  if (defaultsCollapsed.length === 0) return;
  setCollapsedProjects((current) => {
    const next = new Set(current);
    for (const project of defaultsCollapsed) next.add(project.workspaceId);
    return next;
  });
}, [activeProjectId, projects]);

const toggleProject = useCallback((workspaceId: string) => {
  setCollapsedProjects((current) => {
    const next = new Set(current);
    if (next.has(workspaceId)) next.delete(workspaceId);
    else next.add(workspaceId);
    persistCollapsedProjects(next);
    return next;
  });
}, []);

const worktreesByProject = useMemo(
  () => groupWorktreesByProject(worktrees, projects, activeProjectId),
  [activeProjectId, projects, worktrees],
);

